/**
 * Registry of named instrument patches (kit 1.11.0 Timbre Range): pad, bass,
 * lead, pluck and bell classes. A patch is DATA interpreted by an engine in
 * src/kit/band.js. A score selects patches with `patches: { pad: "glass-fm" }`
 * (whole score), a track-level `patches`, or an event's `opts.patch`.
 */
import { PATCHES_PAD } from './pad.mjs';
import { PATCHES_BASS } from './bass.mjs';
import { PATCHES_LEAD } from './lead.mjs';
import { PATCHES_PLUCK } from './pluck.mjs';
import { PATCHES_BELL } from './bell.mjs';
// Sample-backed patches: GENERATED by tools/build-timbre-packs.mjs.
import { PATCHES_SAMPLED } from './sampled.mjs';

import { TRIMS } from '../trims.mjs';

const ALL = [...PATCHES_PAD, ...PATCHES_BASS, ...PATCHES_LEAD, ...PATCHES_PLUCK, ...PATCHES_BELL, ...PATCHES_SAMPLED];

function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    for (const child of Object.values(value)) deepFreeze(child);
    Object.freeze(value);
  }
  return value;
}

const ids = new Set();
for (const patch of ALL) {
  if (ids.has(patch.id)) throw new Error(`duplicate patch id "${patch.id}"`);
  ids.add(patch.id);
}

/** Patch loudness trim: the engine multiplies its output by `gain`. */
const trimPatch = (patch) => (TRIMS[`patch:${patch.id}`] === undefined ? patch : { ...patch, gain: Number(TRIMS[`patch:${patch.id}`].toFixed(5)) });

export const PATCHES = deepFreeze(Object.fromEntries(ALL.map((patch) => [patch.id, trimPatch(patch)])));
export const PATCH_IDS = Object.freeze(Object.keys(PATCHES));
export const PATCH_IDS_BY_CLASS = deepFreeze(Object.fromEntries(
  ['pad', 'bass', 'lead', 'pluck', 'bell'].map((cls) => [cls, ALL.filter((patch) => patch.class === cls).map((patch) => patch.id)]),
));
